const QUESTIONS=[{"id":1,"phase":"THE SELF","title":"Failure","prompt":"You have tried something three times and failed each time. Which response feels most natural?","answers":[{"text":"Abandon the current method and redesign your approach from the ground up.","scores":{"SH":0,"GE":1,"YU":5,"KF":0,"AS":0,"RE":0,"KA":3,"MI":5,"MA":0,"RI":4,"AO":2,"KW":2,"HY":0,"PP":4,"MR":5,"TJ":1}},{"text":"Work out exactly where the previous attempts failed.","scores":{"SH":1,"GE":3,"YU":2,"KF":4,"AS":0,"RE":2,"KA":3,"MI":2,"MA":5,"RI":4,"AO":5,"KW":0,"HY":5,"PP":0,"MR":1,"TJ":2}},{"text":"Question whether the objective is worth pursuing at all.","scores":{"SH":5,"GE":0,"YU":2,"KF":4,"AS":0,"RE":4,"KA":5,"MI":0,"MA":0,"RI":2,"AO":0,"KW":2,"HY":0,"PP":4,"MR":0,"TJ":0}},{"text":"Try again with only small adjustments, because persistence matters more than changing direction.","scores":{"SH":2,"GE":5,"YU":0,"KF":3,"AS":5,"RE":2,"KA":0,"MI":2,"MA":2,"RI":0,"AO":0,"KW":5,"HY":2,"PP":0,"MR":0,"TJ":4}}]},{"id":2,"phase":"THE SELF","title":"Being Underestimated","prompt":"Someone assumes you're less capable than you actually are. Your reaction is closest to:","answers":[{"text":"Make a deliberate effort to demonstrate that they've underestimated you.","scores":{"SH":3,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":2,"MA":2,"RI":4,"AO":0,"KW":0,"HY":0,"PP":0,"MR":3,"TJ":3}},{"text":"Carry on as normal and let the quality of what you do speak for itself.","scores":{"SH":2,"GE":5,"YU":5,"KF":5,"AS":1,"RE":3,"KA":3,"MI":0,"MA":5,"RI":4,"AO":5,"KW":2,"HY":5,"PP":2,"MR":2,"TJ":4}},{"text":"Wondering what made them reach that conclusion.","scores":{"SH":5,"GE":0,"YU":3,"KF":2,"AS":2,"RE":5,"KA":3,"MI":0,"MA":3,"RI":2,"AO":0,"KW":5,"HY":2,"PP":0,"MR":0,"TJ":0}},{"text":"Finding the situation faintly amusing.","scores":{"SH":0,"GE":0,"YU":2,"KF":1,"AS":0,"RE":0,"KA":5,"MI":2,"MA":0,"RI":0,"AO":2,"KW":3,"HY":0,"PP":5,"MR":5,"TJ":1}}]},{"id":3,"phase":"THE SELF","title":"Praise","prompt":"Someone gives you sincere praise for something you did well. What is your most natural reaction?","answers":[{"text":"Feel uncomfortable being singled out and wish the attention would move elsewhere.","scores":{"SH":5,"GE":0,"YU":1,"KF":2,"AS":2,"RE":4,"KA":0,"MI":0,"MA":4,"RI":2,"AO":2,"KW":1,"HY":2,"PP":0,"MR":0,"TJ":0}},{"text":"Accept it readily; knowing that my work was recognised is useful feedback.","scores":{"SH":0,"GE":5,"YU":2,"KF":4,"AS":2,"RE":0,"KA":0,"MI":0,"MA":0,"RI":5,"AO":2,"KW":0,"HY":2,"PP":0,"MR":1,"TJ":1}},{"text":"Enjoy the compliment, then move on without thinking much more about it.","scores":{"SH":0,"GE":2,"YU":3,"KF":0,"AS":2,"RE":0,"KA":2,"MI":5,"MA":0,"RI":0,"AO":0,"KW":2,"HY":2,"PP":5,"MR":5,"TJ":4}},{"text":"Become curious about what specifically made them notice or value what I did.","scores":{"SH":3,"GE":0,"YU":5,"KF":2,"AS":0,"RE":5,"KA":2,"MI":0,"MA":0,"RI":2,"AO":0,"KW":5,"HY":0,"PP":0,"MR":2,"TJ":0}}]},{"id":4,"phase":"THE SELF","title":"Responsibility","prompt":"You discover that a decision you made months ago has unexpectedly affected somebody else's life. Which thought comes closest to your reaction?","answers":[{"text":"I need to understand exactly what happened before I decide what to do.","scores":{"SH":1,"GE":3,"YU":0,"KF":4,"AS":0,"RE":2,"KA":2,"MI":0,"MA":5,"RI":5,"AO":5,"KW":1,"HY":5,"PP":0,"MR":0,"TJ":0}},{"text":"I knew there was a possibility this would happen.","scores":{"SH":0,"GE":5,"YU":2,"KF":4,"AS":2,"RE":0,"KA":5,"MI":2,"MA":0,"RI":3,"AO":2,"KW":0,"HY":0,"PP":0,"MR":2,"TJ":0}},{"text":"I should probably tell them, even if it makes things worse.","scores":{"SH":5,"GE":0,"YU":2,"KF":0,"AS":2,"RE":2,"KA":0,"MI":3,"MA":3,"RI":0,"AO":0,"KW":5,"HY":3,"PP":0,"MR":0,"TJ":2}},{"text":"What matters now is what we do with the situation we've inherited.","scores":{"SH":1,"GE":3,"YU":5,"KF":4,"AS":4,"RE":2,"KA":2,"MI":5,"MA":2,"RI":2,"AO":2,"KW":1,"HY":3,"PP":2,"MR":5,"TJ":4}}]},{"id":5,"phase":"THE SELF","title":"Rules","prompt":"You encounter a rule that clearly makes a situation less effective. What is your instinct?","answers":[{"text":"Understand why the rule exists before deciding whether to bend it.","scores":{"SH":0,"GE":2,"YU":4,"KF":5,"AS":0,"RE":3,"KA":4,"MI":0,"MA":3,"RI":5,"AO":3,"KW":2,"HY":2,"PP":2,"MR":2,"TJ":1}},{"text":"Follow it by default; inefficiency alone isn't enough reason to disregard a rule.","scores":{"SH":2,"GE":0,"YU":0,"KF":3,"AS":0,"RE":5,"KA":0,"MI":2,"MA":5,"RI":2,"AO":3,"KW":0,"HY":5,"PP":2,"MR":0,"TJ":2}},{"text":"Work around it without making an issue of it.","scores":{"SH":0,"GE":5,"YU":2,"KF":2,"AS":1,"RE":3,"KA":4,"MI":0,"MA":0,"RI":3,"AO":5,"KW":2,"HY":2,"PP":4,"MR":5,"TJ":0}},{"text":"Break it openly if the situation demands it.","scores":{"SH":0,"GE":2,"YU":4,"KF":0,"AS":5,"RE":0,"KA":3,"MI":5,"MA":0,"RI":0,"AO":0,"KW":2,"HY":0,"PP":0,"MR":3,"TJ":3}}]},{"id":6,"phase":"THE SELF","title":"Competence Without Recognition","prompt":"You become extremely good at something important, but almost nobody will ever know what you contributed. Which aspect of that situation matters most to you?","answers":[{"text":"Fine. The work matters more than being associated with it.","scores":{"SH":3,"GE":3,"YU":4,"KF":5,"AS":0,"RE":2,"KA":3,"MI":2,"MA":3,"RI":2,"AO":4,"KW":2,"HY":5,"PP":4,"MR":2,"TJ":4}},{"text":"I can accept it, but I'd be lying if I said recognition didn't matter.","scores":{"SH":5,"GE":0,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":4,"MA":5,"RI":2,"AO":0,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":0}},{"text":"I'd rather use that competence somewhere my contribution can have a visible effect.","scores":{"SH":3,"GE":3,"YU":4,"KF":2,"AS":3,"RE":0,"KA":3,"MI":4,"MA":2,"RI":2,"AO":2,"KW":2,"HY":3,"PP":2,"MR":3,"TJ":2}},{"text":"Being underestimated gives me more freedom than being recognised.","scores":{"SH":0,"GE":5,"YU":2,"KF":3,"AS":1,"RE":0,"KA":5,"MI":0,"MA":0,"RI":0,"AO":4,"KW":0,"HY":0,"PP":4,"MR":5,"TJ":1}}]},{"id":7,"phase":"OTHERS","title":"An Uncomfortable Truth","prompt":"Someone you respect tells you something about yourself that you don't particularly want to hear. Your first instinct is to:","answers":[{"text":"Examine whether they're actually right before deciding how you feel about it.","scores":{"SH":0,"GE":3,"YU":4,"KF":5,"AS":0,"RE":3,"KA":3,"MI":2,"MA":5,"RI":5,"AO":5,"KW":3,"HY":5,"PP":0,"MR":2,"TJ":0}},{"text":"Ask why they chose to tell you now.","scores":{"SH":0,"GE":5,"YU":2,"KF":3,"AS":2,"RE":2,"KA":5,"MI":2,"MA":2,"RI":3,"AO":2,"KW":5,"HY":2,"PP":0,"MR":2,"TJ":1}},{"text":"Dismiss it initially, then find yourself thinking about it later.","scores":{"SH":5,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":5,"MA":0,"RI":0,"AO":0,"KW":0,"HY":0,"PP":2,"MR":0,"TJ":2}},{"text":"Accept that their perspective is valid even if you don't agree with it.","scores":{"SH":0,"GE":0,"YU":4,"KF":2,"AS":0,"RE":5,"KA":2,"MI":0,"MA":3,"RI":0,"AO":2,"KW":3,"HY":2,"PP":4,"MR":5,"TJ":4}}]},{"id":8,"phase":"OTHERS","title":"The Difficult Person","prompt":"Someone on your team is talented but difficult. Their challenges sometimes make cooperation exhausting. What would make you most willing to tolerate the friction?","answers":[{"text":"They prevent the group from becoming complacent.","scores":{"SH":0,"GE":4,"YU":0,"KF":2,"AS":2,"RE":0,"KA":0,"MI":4,"MA":0,"RI":4,"AO":0,"KW":0,"HY":0,"PP":0,"MR":2,"TJ":1}},{"text":"They identify problems other people avoid saying aloud.","scores":{"SH":0,"GE":4,"YU":0,"KF":2,"AS":0,"RE":0,"KA":2,"MI":2,"MA":2,"RI":4,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":3}},{"text":"Their challenges force better reasoning and clearer decisions.","scores":{"SH":4,"GE":2,"YU":2,"KF":5,"AS":0,"RE":4,"KA":2,"MI":4,"MA":0,"RI":2,"AO":0,"KW":5,"HY":2,"PP":0,"MR":0,"TJ":0}},{"text":"Their best work emerges when they're given enough independence.","scores":{"SH":4,"GE":0,"YU":5,"KF":0,"AS":0,"RE":4,"KA":0,"MI":0,"MA":0,"RI":0,"AO":0,"KW":3,"HY":0,"PP":4,"MR":5,"TJ":4}}]},{"id":9,"phase":"OTHERS","title":"What People Owe Each Other","prompt":"When another person's choices begin affecting the people around them, which principle are you least willing to compromise?","answers":[{"text":"People should ultimately answer for the consequences of choices they make.","scores":{"SH":2,"GE":4,"YU":3,"KF":2,"AS":3,"RE":0,"KA":5,"MI":0,"MA":4,"RI":5,"AO":3,"KW":2,"HY":2,"PP":1,"MR":4,"TJ":4}},{"text":"People shouldn't be expected to carry serious problems entirely alone.","scores":{"SH":5,"GE":2,"YU":3,"KF":0,"AS":2,"RE":3,"KA":3,"MI":2,"MA":4,"RI":0,"AO":1,"KW":5,"HY":2,"PP":3,"MR":3,"TJ":3}},{"text":"A person's right to determine their own path should be interfered with only in exceptional circumstances.","scores":{"SH":2,"GE":0,"YU":5,"KF":2,"AS":5,"RE":5,"KA":3,"MI":0,"MA":4,"RI":0,"AO":5,"KW":4,"HY":2,"PP":5,"MR":5,"TJ":1}},{"text":"Sometimes preventing serious harm justifies acting before someone is ready to accept help.","scores":{"SH":0,"GE":5,"YU":0,"KF":0,"AS":0,"RE":0,"KA":0,"MI":0,"MA":0,"RI":2,"AO":0,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":0}}]},{"id":10,"phase":"OTHERS","title":"The Empty Chair","prompt":"You're waiting for someone who is very late and you have no way to know whether they'll arrive. What best describes your response to the uncertainty?","answers":[{"text":"The waiting doesn't bother me; I can redirect my attention until something changes.","scores":{"SH":2,"GE":4,"YU":3,"KF":3,"AS":3,"RE":2,"KA":3,"MI":3,"MA":4,"RI":5,"AO":5,"KW":2,"HY":4,"PP":5,"MR":5,"TJ":4}},{"text":"My mind starts generating possible explanations for their absence.","scores":{"SH":4,"GE":4,"YU":3,"KF":5,"AS":3,"RE":3,"KA":5,"MI":2,"MA":4,"RI":3,"AO":3,"KW":3,"HY":4,"PP":1,"MR":0,"TJ":0}},{"text":"Not knowing whether I'm wasting my time becomes increasingly frustrating.","scores":{"SH":4,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":5,"MA":0,"RI":2,"AO":0,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":1}},{"text":"I settle into the uncertainty itself and don't particularly need an answer yet.","scores":{"SH":0,"GE":0,"YU":5,"KF":3,"AS":0,"RE":5,"KA":3,"MI":0,"MA":2,"RI":0,"AO":3,"KW":5,"HY":2,"PP":4,"MR":2,"TJ":2}}]},{"id":11,"phase":"OTHERS","title":"When Someone Is Hurting","prompt":"You realise that someone close to you is struggling but hasn't asked for help. What do you do?","answers":[{"text":"Stay close and let them decide whether silence becomes conversation.","scores":{"SH":2,"GE":0,"YU":2,"KF":2,"AS":0,"RE":2,"KA":0,"MI":2,"MA":0,"RI":0,"AO":2,"KW":3,"HY":2,"PP":5,"MR":0,"TJ":2}},{"text":"Take care of something practical that makes their situation easier.","scores":{"SH":0,"GE":4,"YU":0,"KF":4,"AS":0,"RE":0,"KA":2,"MI":2,"MA":0,"RI":5,"AO":5,"KW":0,"HY":2,"PP":3,"MR":0,"TJ":4}},{"text":"Ask directly what kind of support, if any, they want.","scores":{"SH":2,"GE":0,"YU":2,"KF":0,"AS":0,"RE":0,"KA":2,"MI":5,"MA":0,"RI":0,"AO":0,"KW":5,"HY":0,"PP":0,"MR":2,"TJ":1}},{"text":"Step back unless they reach out, while making it clear the door is open.","scores":{"SH":0,"GE":2,"YU":5,"KF":4,"AS":2,"RE":5,"KA":0,"MI":0,"MA":2,"RI":2,"AO":3,"KW":3,"HY":0,"PP":3,"MR":2,"TJ":0}}]},{"id":12,"phase":"OTHERS","title":"A Choice You Don't Understand","prompt":"Someone you care deeply about makes a life choice you would never make yourself, but they seem genuinely happy with it. If you could know only one thing for certain, what would matter most?","answers":[{"text":"That they are happy, even if I never fully understand the choice.","scores":{"SH":0,"GE":0,"YU":0,"KF":0,"AS":0,"RE":2,"KA":0,"MI":0,"MA":0,"RI":0,"AO":0,"KW":4,"HY":0,"PP":3,"MR":2,"TJ":4}},{"text":"Understanding what the choice means to them.","scores":{"SH":2,"GE":1,"YU":0,"KF":2,"AS":2,"RE":4,"KA":4,"MI":0,"MA":0,"RI":2,"AO":2,"KW":4,"HY":0,"PP":0,"MR":0,"TJ":0}},{"text":"Knowing the decision is truly theirs rather than something imposed on them.","scores":{"SH":0,"GE":0,"YU":2,"KF":2,"AS":5,"RE":4,"KA":2,"MI":0,"MA":2,"RI":2,"AO":4,"KW":2,"HY":0,"PP":5,"MR":5,"TJ":3}},{"text":"Whether the happiness will survive the consequences of the decision.","scores":{"SH":2,"GE":5,"YU":0,"KF":5,"AS":3,"RE":0,"KA":4,"MI":2,"MA":0,"RI":5,"AO":4,"KW":0,"HY":2,"PP":0,"MR":2,"TJ":1}}]},{"id":13,"phase":"PRESSURE","title":"The Unplanned Variable","prompt":"A project you've invested heavily in suddenly goes off course. Nobody is immediately blaming you, but the outcome is clearly going to be worse than expected. What bothers you most?","answers":[{"text":"Knowing that a better decision probably existed, if you'd been able to see it in time.","scores":{"SH":5,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":2,"MA":2,"RI":0,"AO":0,"KW":2,"HY":0,"PP":0,"MR":0,"TJ":2}},{"text":"Having to keep moving when you don't yet understand what happened.","scores":{"SH":3,"GE":0,"YU":0,"KF":2,"AS":2,"RE":0,"KA":2,"MI":0,"MA":0,"RI":0,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":0}},{"text":"Watching everyone become preoccupied with blame instead of solving the problem.","scores":{"SH":2,"GE":2,"YU":2,"KF":0,"AS":2,"RE":0,"KA":4,"MI":5,"MA":0,"RI":0,"AO":0,"KW":2,"HY":2,"PP":2,"MR":5,"TJ":4}},{"text":"The possibility that the setback reveals something fundamental about the plan itself.","scores":{"SH":0,"GE":5,"YU":5,"KF":0,"AS":0,"RE":2,"KA":4,"MI":0,"MA":0,"RI":2,"AO":0,"KW":5,"HY":0,"PP":0,"MR":2,"TJ":1}}]},{"id":14,"phase":"PRESSURE","title":"The Unknown","prompt":"You're offered the opportunity to enter somewhere completely unfamiliar with no guarantee that it will be worthwhile. Your strongest feeling is:","answers":[{"text":"Curiosity.","scores":{"SH":1,"GE":3,"YU":5,"KF":3,"AS":2,"RE":3,"KA":5,"MI":2,"MA":2,"RI":5,"AO":3,"KW":3,"HY":2,"PP":2,"MR":5,"TJ":0}},{"text":"Caution.","scores":{"SH":3,"GE":5,"YU":0,"KF":5,"AS":0,"RE":5,"KA":0,"MI":0,"MA":5,"RI":3,"AO":5,"KW":0,"HY":5,"PP":0,"MR":0,"TJ":1}},{"text":"Excitement.","scores":{"SH":0,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":2,"MI":5,"MA":0,"RI":2,"AO":0,"KW":2,"HY":0,"PP":3,"MR":3,"TJ":1}},{"text":"A desire to know who else is going.","scores":{"SH":5,"GE":0,"YU":0,"KF":1,"AS":2,"RE":2,"KA":0,"MI":2,"MA":2,"RI":0,"AO":0,"KW":5,"HY":3,"PP":5,"MR":2,"TJ":3}}]},{"id":15,"phase":"PRESSURE","title":"The Group Problem","prompt":"A team you've joined has developed an unspoken disagreement. Everyone is being polite, but nobody is addressing it. What happens next?","answers":[{"text":"You eventually bring the issue into the open.","scores":{"SH":2,"GE":2,"YU":2,"KF":0,"AS":5,"RE":0,"KA":0,"MI":5,"MA":2,"RI":0,"AO":0,"KW":3,"HY":5,"PP":0,"MR":2,"TJ":2}},{"text":"You try to understand each person's position first.","scores":{"SH":5,"GE":0,"YU":2,"KF":5,"AS":0,"RE":5,"KA":2,"MI":2,"MA":5,"RI":2,"AO":2,"KW":5,"HY":2,"PP":0,"MR":0,"TJ":4}},{"text":"You watch for the point at which the disagreement becomes actionable.","scores":{"SH":0,"GE":3,"YU":0,"KF":2,"AS":0,"RE":2,"KA":0,"MI":0,"MA":2,"RI":2,"AO":5,"KW":0,"HY":2,"PP":2,"MR":0,"TJ":0}},{"text":"You suggest changing the environment or task so the disagreement becomes irrelevant.","scores":{"SH":0,"GE":5,"YU":5,"KF":0,"AS":2,"RE":0,"KA":0,"MI":2,"MA":0,"RI":5,"AO":2,"KW":0,"HY":0,"PP":4,"MR":5,"TJ":1}}]},{"id":16,"phase":"PRESSURE","title":"The Sacrifice","prompt":"One person voluntarily offers to accept a serious personal cost that would resolve a crisis for everyone else. Before accepting their offer, what would you need to be most certain of?","answers":[{"text":"That they understand the cost and are choosing freely.","scores":{"SH":4,"GE":1,"YU":2,"KF":0,"AS":2,"RE":5,"KA":2,"MI":0,"MA":2,"RI":0,"AO":0,"KW":5,"HY":2,"PP":0,"MR":2,"TJ":2}},{"text":"That nobody has pressured them into believing they owe everyone this sacrifice.","scores":{"SH":4,"GE":0,"YU":0,"KF":0,"AS":2,"RE":2,"KA":2,"MI":2,"MA":2,"RI":0,"AO":0,"KW":2,"HY":0,"PP":0,"MR":0,"TJ":4}},{"text":"That their sacrifice genuinely solves the problem rather than postponing it.","scores":{"SH":0,"GE":4,"YU":0,"KF":2,"AS":0,"RE":0,"KA":0,"MI":0,"MA":0,"RI":5,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":1}},{"text":"That refusing their offer would not create an even greater cost they themselves wanted to prevent.","scores":{"SH":2,"GE":5,"YU":0,"KF":0,"AS":2,"RE":2,"KA":0,"MI":2,"MA":0,"RI":2,"AO":0,"KW":0,"HY":0,"PP":2,"MR":0,"TJ":0}}]},{"id":17,"phase":"PRESSURE","title":"The Impossible Choice","prompt":"You have two options. One has a 70% chance of producing a mediocre outcome. The other has a 30% chance of producing something extraordinary and a 70% chance of going badly. You lean towards:","answers":[{"text":"The reliable option. A predictable outcome has value.","scores":{"SH":4,"GE":0,"YU":0,"KF":3,"AS":0,"RE":3,"KA":0,"MI":2,"MA":5,"RI":0,"AO":5,"KW":0,"HY":5,"PP":2,"MR":0,"TJ":1}},{"text":"The risky option. Extraordinary opportunities rarely arrive safely packaged.","scores":{"SH":0,"GE":2,"YU":3,"KF":0,"AS":5,"RE":0,"KA":3,"MI":3,"MA":0,"RI":2,"AO":0,"KW":2,"HY":0,"PP":2,"MR":3,"TJ":2}},{"text":"Waiting for more information, even if that means losing both opportunities.","scores":{"SH":4,"GE":0,"YU":2,"KF":5,"AS":0,"RE":5,"KA":2,"MI":0,"MA":3,"RI":2,"AO":3,"KW":2,"HY":3,"PP":0,"MR":0,"TJ":0}},{"text":"Finding a third option that changes the terms of the choice.","scores":{"SH":0,"GE":2,"YU":5,"KF":3,"AS":3,"RE":2,"KA":5,"MI":5,"MA":2,"RI":5,"AO":3,"KW":5,"HY":2,"PP":0,"MR":5,"TJ":4}}]},{"id":18,"phase":"PRESSURE","title":"The Cost of Control","prompt":"A situation you care deeply about is slipping beyond your control. You can still influence what happens, but you cannot guarantee the outcome. What do you do?","answers":[{"text":"Tighten my control over the parts I can still influence.","scores":{"SH":0,"GE":5,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":0,"MA":0,"RI":4,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":2}},{"text":"Prepare for several outcomes rather than trying to force one.","scores":{"SH":0,"GE":4,"YU":4,"KF":2,"AS":2,"RE":3,"KA":4,"MI":2,"MA":2,"RI":4,"AO":5,"KW":3,"HY":5,"PP":4,"MR":5,"TJ":1}},{"text":"Trust the people involved to make choices I cannot make for them.","scores":{"SH":2,"GE":0,"YU":4,"KF":0,"AS":0,"RE":5,"KA":3,"MI":0,"MA":2,"RI":0,"AO":0,"KW":3,"HY":2,"PP":4,"MR":2,"TJ":4}},{"text":"Ask myself whether my need to control the outcome has become part of the problem.","scores":{"SH":5,"GE":1,"YU":3,"KF":0,"AS":2,"RE":3,"KA":4,"MI":0,"MA":2,"RI":3,"AO":0,"KW":5,"HY":0,"PP":2,"MR":3,"TJ":0}}]},{"id":19,"phase":"IDENTITY","title":"Irreversible Change","prompt":"Something important in your life changes in a way that cannot be undone. When the initial shock has passed, what most helps you begin moving forward?","answers":[{"text":"Finding something meaningful that can still be built from the new situation.","scores":{"SH":3,"GE":1,"YU":5,"KF":3,"AS":2,"RE":3,"KA":2,"MI":2,"MA":2,"RI":0,"AO":0,"KW":2,"HY":2,"PP":2,"MR":2,"TJ":4}},{"text":"Understanding what has actually changed before reacting.","scores":{"SH":2,"GE":5,"YU":2,"KF":5,"AS":0,"RE":3,"KA":0,"MI":0,"MA":5,"RI":5,"AO":5,"KW":0,"HY":2,"PP":0,"MR":0,"TJ":0}},{"text":"Accepting that resisting the change will not restore the past.","scores":{"SH":5,"GE":0,"YU":2,"KF":3,"AS":0,"RE":5,"KA":0,"MI":2,"MA":2,"RI":0,"AO":2,"KW":5,"HY":2,"PP":3,"MR":2,"TJ":2}},{"text":"Throwing yourself into something new rather than dwelling on what was lost.","scores":{"SH":0,"GE":2,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":5,"MA":0,"RI":0,"AO":0,"KW":0,"HY":0,"PP":5,"MR":5,"TJ":1}}]},{"id":20,"phase":"IDENTITY","title":"The Future","prompt":"When you imagine yourself ten years from now, which aspect matters most?","answers":[{"text":"Having built something that continues after you.","scores":{"SH":0,"GE":5,"YU":2,"KF":4,"AS":0,"RE":0,"KA":0,"MI":2,"MA":0,"RI":4,"AO":0,"KW":0,"HY":2,"PP":0,"MR":0,"TJ":2}},{"text":"Being surrounded by people you trust.","scores":{"SH":5,"GE":1,"YU":0,"KF":0,"AS":2,"RE":2,"KA":0,"MI":5,"MA":2,"RI":0,"AO":0,"KW":4,"HY":5,"PP":4,"MR":0,"TJ":4}},{"text":"Having understood something that once seemed impossible.","scores":{"SH":0,"GE":3,"YU":2,"KF":4,"AS":0,"RE":2,"KA":2,"MI":0,"MA":0,"RI":4,"AO":5,"KW":3,"HY":0,"PP":2,"MR":2,"TJ":0}},{"text":"Knowing that you lived according to your own choices.","scores":{"SH":3,"GE":0,"YU":2,"KF":2,"AS":5,"RE":5,"KA":2,"MI":2,"MA":0,"RI":0,"AO":2,"KW":4,"HY":2,"PP":5,"MR":5,"TJ":1}}]},{"id":21,"phase":"IDENTITY","title":"The Quiet Moment","prompt":"You unexpectedly have an entire evening with no obligations and enough energy to do whatever you like. With nobody else influencing the choice, where do you naturally drift?","answers":[{"text":"Going somewhere you've never been.","scores":{"SH":0,"GE":0,"YU":2,"KF":0,"AS":5,"RE":0,"KA":2,"MI":3,"MA":0,"RI":2,"AO":2,"KW":0,"HY":0,"PP":4,"MR":5,"TJ":2}},{"text":"Being with someone you enjoy without needing to do anything.","scores":{"SH":5,"GE":0,"YU":2,"KF":2,"AS":2,"RE":5,"KA":0,"MI":5,"MA":4,"RI":0,"AO":0,"KW":2,"HY":5,"PP":3,"MR":0,"TJ":1}},{"text":"Working on something purely because you're interested in it.","scores":{"SH":0,"GE":5,"YU":5,"KF":5,"AS":2,"RE":2,"KA":2,"MI":0,"MA":4,"RI":5,"AO":2,"KW":0,"HY":2,"PP":0,"MR":2,"TJ":0}},{"text":"Doing absolutely nothing and enjoying the absence of demands.","scores":{"SH":3,"GE":0,"YU":0,"KF":3,"AS":0,"RE":2,"KA":0,"MI":3,"MA":2,"RI":0,"AO":5,"KW":0,"HY":2,"PP":4,"MR":0,"TJ":4}}]},{"id":22,"phase":"IDENTITY","title":"The Old Photograph","prompt":"You find an old photograph of yourself with people you haven't seen in years. After the initial glance, what is most likely to hold your attention?","answers":[{"text":"How much everyone has changed since then.","scores":{"SH":0,"GE":0,"YU":0,"KF":2,"AS":2,"RE":0,"KA":0,"MI":0,"MA":0,"RI":0,"AO":2,"KW":0,"HY":0,"PP":5,"MR":2,"TJ":1}},{"text":"The memories surrounding the moment that the photograph cannot show.","scores":{"SH":5,"GE":3,"YU":5,"KF":2,"AS":2,"RE":4,"KA":5,"MI":4,"MA":2,"RI":2,"AO":2,"KW":5,"HY":2,"PP":1,"MR":2,"TJ":4}},{"text":"The people or relationships that are absent from the frame.","scores":{"SH":2,"GE":5,"YU":2,"KF":2,"AS":0,"RE":4,"KA":2,"MI":4,"MA":0,"RI":5,"AO":0,"KW":2,"HY":0,"PP":0,"MR":0,"TJ":2}},{"text":"What someone's expression suggests they were feeling at the time.","scores":{"SH":2,"GE":0,"YU":2,"KF":0,"AS":5,"RE":2,"KA":2,"MI":2,"MA":5,"RI":0,"AO":2,"KW":2,"HY":5,"PP":0,"MR":2,"TJ":0}}]},{"id":23,"phase":"IDENTITY","title":"Your Greatest Weakness","prompt":"Which would be hardest for you to admit?","answers":[{"text":"I need someone.","scores":{"SH":5,"GE":2,"YU":0,"KF":0,"AS":2,"RE":5,"KA":0,"MI":2,"MA":0,"RI":2,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":4}},{"text":"I don't know what I'm doing.","scores":{"SH":0,"GE":0,"YU":2,"KF":5,"AS":0,"RE":2,"KA":5,"MI":0,"MA":5,"RI":0,"AO":5,"KW":1,"HY":2,"PP":2,"MR":2,"TJ":1}},{"text":"I'm afraid of losing control.","scores":{"SH":0,"GE":2,"YU":0,"KF":2,"AS":0,"RE":0,"KA":0,"MI":0,"MA":0,"RI":0,"AO":2,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":0}},{"text":"I don't know whether I'm happy.","scores":{"SH":2,"GE":0,"YU":2,"KF":0,"AS":0,"RE":3,"KA":0,"MI":0,"MA":0,"RI":0,"AO":0,"KW":5,"HY":0,"PP":0,"MR":0,"TJ":2}}]},{"id":24,"phase":"IDENTITY","title":"Classified Information","prompt":"You discover confidential information that changes your understanding of a decision already in motion. Nobody knows you have seen it. What is your first priority?","answers":[{"text":"Verify whether the information is accurate before drawing conclusions from it.","scores":{"SH":0,"GE":1,"YU":3,"KF":2,"AS":0,"RE":0,"KA":0,"MI":2,"MA":3,"RI":5,"AO":2,"KW":1,"HY":2,"PP":2,"MR":0,"TJ":2}},{"text":"Work out who already knew it and why it was being withheld.","scores":{"SH":0,"GE":3,"YU":2,"KF":5,"AS":2,"RE":0,"KA":5,"MI":2,"MA":1,"RI":3,"AO":0,"KW":2,"HY":0,"PP":0,"MR":2,"TJ":0}},{"text":"Decide whether staying silent would expose someone to harm or leave a responsibility unmet.","scores":{"SH":5,"GE":0,"YU":5,"KF":0,"AS":4,"RE":5,"KA":0,"MI":5,"MA":5,"RI":0,"AO":0,"KW":5,"HY":5,"PP":2,"MR":5,"TJ":4}},{"text":"Keep it compartmentalised until revealing it would materially change what happens.","scores":{"SH":2,"GE":5,"YU":0,"KF":3,"AS":0,"RE":0,"KA":2,"MI":0,"MA":0,"RI":3,"AO":5,"KW":0,"HY":0,"PP":4,"MR":0,"TJ":1}}]},{"id":25,"phase":"SYNCHRONISATION","title":"A Personal Boundary","prompt":"Someone you trust deeply wants to know something personal that you're not ready to share. You believe their concern is genuine. What would you most naturally do?","answers":[{"text":"Give them part of the truth.","scores":{"SH":0,"GE":5,"YU":3,"KF":5,"AS":2,"RE":5,"KA":2,"MI":2,"MA":2,"RI":5,"AO":4,"KW":2,"HY":2,"PP":1,"MR":0,"TJ":1}},{"text":"Refuse, but try not to make them feel rejected.","scores":{"SH":0,"GE":2,"YU":3,"KF":2,"AS":2,"RE":2,"KA":0,"MI":0,"MA":5,"RI":2,"AO":4,"KW":5,"HY":5,"PP":2,"MR":0,"TJ":2}},{"text":"Change the subject until the moment passes.","scores":{"SH":2,"GE":3,"YU":0,"KF":0,"AS":5,"RE":0,"KA":2,"MI":2,"MA":0,"RI":2,"AO":2,"KW":0,"HY":0,"PP":5,"MR":5,"TJ":0}},{"text":"Tell them, because withholding it feels more damaging than revealing it.","scores":{"SH":0,"GE":0,"YU":5,"KF":0,"AS":0,"RE":2,"KA":0,"MI":5,"MA":2,"RI":0,"AO":0,"KW":3,"HY":2,"PP":0,"MR":0,"TJ":4}}]},{"id":26,"phase":"SYNCHRONISATION","title":"When Nobody Is Watching","prompt":"You have a responsibility that nobody will know you failed to complete unless you choose to say so. What matters most?","answers":[{"text":"Doing it properly because someone may eventually depend on it.","scores":{"SH":3,"GE":2,"YU":2,"KF":4,"AS":2,"RE":2,"KA":2,"MI":4,"MA":4,"RI":4,"AO":2,"KW":2,"HY":4,"PP":2,"MR":0,"TJ":4}},{"text":"Being honest about what happened, even if there are consequences.","scores":{"SH":5,"GE":0,"YU":0,"KF":0,"AS":2,"RE":2,"KA":4,"MI":2,"MA":4,"RI":0,"AO":0,"KW":2,"HY":4,"PP":0,"MR":0,"TJ":3}},{"text":"Deciding whether the task still matters before spending effort on it.","scores":{"SH":0,"GE":3,"YU":0,"KF":2,"AS":0,"RE":0,"KA":4,"MI":0,"MA":0,"RI":4,"AO":2,"KW":0,"HY":0,"PP":5,"MR":2,"TJ":0}},{"text":"Finish it simply because I said I would, even if I now doubt whether anyone will benefit.","scores":{"SH":3,"GE":5,"YU":0,"KF":4,"AS":5,"RE":2,"KA":0,"MI":4,"MA":4,"RI":3,"AO":2,"KW":5,"HY":4,"PP":1,"MR":0,"TJ":1}}]},{"id":27,"phase":"SYNCHRONISATION","title":"Authority","prompt":"Your superior gives you an order that you believe is technically correct but ethically questionable. You are most likely to:","answers":[{"text":"Follow it, while documenting your concerns.","scores":{"SH":0,"GE":2,"YU":0,"KF":4,"AS":0,"RE":4,"KA":0,"MI":0,"MA":2,"RI":2,"AO":2,"KW":0,"HY":2,"PP":3,"MR":0,"TJ":1}},{"text":"Challenge the order directly.","scores":{"SH":0,"GE":0,"YU":3,"KF":0,"AS":5,"RE":0,"KA":3,"MI":4,"MA":5,"RI":0,"AO":0,"KW":2,"HY":0,"PP":0,"MR":3,"TJ":4}},{"text":"Find a way to achieve the intended objective without following the questionable part.","scores":{"SH":0,"GE":5,"YU":4,"KF":2,"AS":2,"RE":2,"KA":3,"MI":4,"MA":0,"RI":2,"AO":0,"KW":5,"HY":5,"PP":4,"MR":5,"TJ":2}},{"text":"Ask for clarification about the underlying objective before acting.","scores":{"SH":0,"GE":3,"YU":4,"KF":4,"AS":1,"RE":4,"KA":5,"MI":2,"MA":2,"RI":5,"AO":0,"KW":3,"HY":2,"PP":2,"MR":2,"TJ":0}}]},{"id":28,"phase":"SYNCHRONISATION","title":"Being Misunderstood","prompt":"Someone important to you has formed an inaccurate impression of why you made a difficult decision. Correcting them would require revealing something deeply personal. What matters most?","answers":[{"text":"Being understood accurately, even if explaining myself feels exposing.","scores":{"SH":5,"GE":0,"YU":3,"KF":1,"AS":3,"RE":1,"KA":3,"MI":5,"MA":3,"RI":1,"AO":0,"KW":4,"HY":3,"PP":0,"MR":1,"TJ":4}},{"text":"Protecting what is private; they don't need to understand everything about me.","scores":{"SH":2,"GE":5,"YU":1,"KF":3,"AS":5,"RE":3,"KA":3,"MI":1,"MA":1,"RI":5,"AO":5,"KW":0,"HY":1,"PP":4,"MR":3,"TJ":1}},{"text":"Whether their misunderstanding will materially affect what happens next.","scores":{"SH":0,"GE":3,"YU":3,"KF":5,"AS":0,"RE":1,"KA":5,"MI":3,"MA":5,"RI":3,"AO":3,"KW":1,"HY":5,"PP":1,"MR":3,"TJ":2}},{"text":"Whether correcting them would actually change how they feel about the decision.","scores":{"SH":3,"GE":2,"YU":2,"KF":3,"AS":3,"RE":5,"KA":3,"MI":3,"MA":1,"RI":3,"AO":2,"KW":5,"HY":1,"PP":0,"MR":2,"TJ":0}}]},{"id":29,"phase":"SYNCHRONISATION","title":"The Troubling Decision","prompt":"Someone you respect makes a decision you believe is wrong. They don't need your permission, but they value your support. What matters most?","answers":[{"text":"Making sure they understand why I think they're wrong, even if it strains the relationship.","scores":{"SH":2,"GE":3,"YU":0,"KF":0,"AS":5,"RE":0,"KA":0,"MI":2,"MA":5,"RI":0,"AO":0,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":2}},{"text":"Helping them deal with the consequences without pretending I agreed with the decision.","scores":{"SH":2,"GE":3,"YU":3,"KF":3,"AS":0,"RE":3,"KA":3,"MI":5,"MA":0,"RI":0,"AO":0,"KW":3,"HY":5,"PP":3,"MR":0,"TJ":4}},{"text":"Understanding what led them there before deciding how strongly to oppose it.","scores":{"SH":0,"GE":5,"YU":3,"KF":5,"AS":0,"RE":3,"KA":5,"MI":0,"MA":0,"RI":5,"AO":2,"KW":3,"HY":2,"PP":0,"MR":0,"TJ":1}},{"text":"Respecting that the choice is theirs unless it places someone else at serious risk.","scores":{"SH":0,"GE":0,"YU":5,"KF":3,"AS":3,"RE":5,"KA":3,"MI":2,"MA":2,"RI":0,"AO":2,"KW":5,"HY":2,"PP":5,"MR":5,"TJ":0}}]},{"id":30,"phase":"SYNCHRONISATION","title":"Final Synchronisation","prompt":"You're given one opportunity to leave a message for someone who may never hear it. What would you most want them to understand?","answers":[{"text":"You were never as alone as you thought.","scores":{"SH":5,"GE":0,"YU":0,"KF":0,"AS":4,"RE":2,"KA":0,"MI":2,"MA":2,"RI":0,"AO":0,"KW":2,"HY":2,"PP":4,"MR":0,"TJ":4}},{"text":"I wanted you to become capable of choosing for yourself.","scores":{"SH":0,"GE":2,"YU":2,"KF":4,"AS":4,"RE":2,"KA":0,"MI":2,"MA":2,"RI":0,"AO":2,"KW":2,"HY":2,"PP":0,"MR":2,"TJ":2}},{"text":"Whatever happened, I don't regret knowing you.","scores":{"SH":2,"GE":4,"YU":2,"KF":4,"AS":4,"RE":0,"KA":2,"MI":2,"MA":2,"RI":2,"AO":2,"KW":2,"HY":5,"PP":4,"MR":2,"TJ":1}},{"text":"There was always more to the story than you could see.","scores":{"SH":0,"GE":4,"YU":2,"KF":4,"AS":0,"RE":2,"KA":2,"MI":0,"MA":0,"RI":5,"AO":5,"KW":0,"HY":0,"PP":0,"MR":0,"TJ":0}}]}];
const CHARACTERS={"SH":{"name":"SHINJI IKARI","title":"The Hesitant Synchronisation","quote":"I mustn't run away.","traits":"Empathy · Reflection · Sensitivity · Attachment","blurb":"You tend to experience decisions emotionally before you experience them rationally. You may hesitate when the consequences of your choices could hurt someone, but that hesitation does not mean you lack courage. You are particularly sensitive to rejection and expectations, and may underestimate your own resilience.","fingerprint":[0.9,0.3,0.25,0.3,0.45,0.8,0.35,0.4],"classification":"THIRD CHILD","accent":"#8E44FF","image":"assets/characters/SH.png"},"GE":{"name":"GENDO IKARI","title":"The Command Synchronisation","quote":"Get in the robot, Shinji.","traits":"Determination · Control · Strategy · Compartmentalisation","blurb":"You tend to solve uncertainty by creating structure around it. You may keep emotions private when you believe expressing them would weaken your ability to achieve an objective. Others may mistake reserve for indifference when you have simply decided that action matters more than explanation.","fingerprint":[0.15,0.95,0.98,0.75,0.25,0.65,0.08,0.35],"classification":"DIRECTOR OF NERV","accent":"#FF3333","image":"assets/characters/GE.png"},"YU":{"name":"YUI IKARI","title":"The Human Synchronisation","quote":"Anywhere can be paradise…","traits":"Curiosity · Optimism · Independence · Vision","blurb":"You tend to look beyond immediate circumstances and consider what might become possible. You can tolerate uncertainty when it serves a larger purpose, and place considerable faith in people's capacity to change. Your optimism is often a deliberate choice rather than naïveté.","fingerprint":[0.65,0.9,0.3,0.3,0.9,0.75,0.8,0.75],"classification":"CHIEF BIO-ENGINEER","accent":"#F7D7C4","image":"assets/characters/YU.png"},"KF":{"name":"KOUZOU FUYUTSUKI","title":"The Observer Synchronisation","quote":"People are creatures that live by memory.","traits":"Patience · Insight · Loyalty · Restraint","blurb":"You rarely need to be the loudest person in the room. You prefer to observe, understand the forces at work and intervene when your contribution matters. Your loyalty tends to be thoughtful rather than unquestioning.","fingerprint":[0.35,0.6,0.65,0.2,0.55,0.75,0.3,0.5],"classification":"VICE-COMMANDER","accent":"#B8B8B8","image":"assets/characters/KF.png"},"AS":{"name":"ASUKA LANGLEY SORYU","title":"The Combative Synchronisation","quote":"I don't want to lose.","traits":"Drive · Independence · Pride · Resilience","blurb":"You derive confidence from competence, but recognition can matter more than you admit. Being underestimated can be particularly motivating. You value independence, while your strongest relationships may be those where you can stop proving you do not need anyone.","fingerprint":[0.3,0.9,0.65,0.98,0.6,0.55,0.35,0.75],"classification":"SECOND CHILD","accent":"#FF3333","image":"assets/characters/AS.png"},"RE":{"name":"REI AYANAMI","title":"The Quiet Synchronisation","quote":"I don't know what this feeling is.","traits":"Acceptance · Introspection · Composure · Curiosity","blurb":"You do not necessarily need to fill silence with explanations. You can accept circumstances others struggle against while remaining quietly curious about who you are and what you want. Your strength lies partly in observing without immediately judging.","fingerprint":[0.7,0.35,0.4,0.15,0.55,0.6,0.2,0.55],"classification":"FIRST CHILD","accent":"#00D9FF","image":"assets/characters/RE.png"},"KA":{"name":"RYOJI KAJI","title":"The Adaptive Synchronisation","quote":"Humans are always looking for something.","traits":"Adaptability · Curiosity · Emotional intelligence · Pragmatism","blurb":"You are comfortable navigating ambiguity and rarely assume the first explanation is the whole story. You can take difficult situations seriously without allowing them to consume you. You value relationships while understanding the importance of personal freedom.","fingerprint":[0.7,0.85,0.4,0.55,0.85,0.65,0.85,0.95],"classification":"SPECIAL INSPECTOR","accent":"#45D06F","image":"assets/characters/KA.png"},"MI":{"name":"MISATO KATSURAGI","title":"The Improvised Synchronisation","quote":"Sometimes you have to live with the consequences.","traits":"Action · Loyalty · Courage · Spontaneity","blurb":"You can function remarkably well when circumstances become chaotic. You may not always have a perfect plan, but you are willing to act when somebody has to. Beneath decisiveness is a strong need for connection that is not always easy to reconcile with responsibility.","fingerprint":[0.7,0.55,0.55,0.75,0.75,0.9,0.7,0.95],"classification":"TACTICAL OPERATIONS DIRECTOR","accent":"#8A5CFF","image":"assets/characters/MI.png"},"MA":{"name":"MAYA IBUKI","title":"The Conscientious Synchronisation","quote":"I don't think I can do this…","traits":"Empathy · Conscientiousness · Ethics · Reliability","blurb":"You take responsibility seriously, particularly when other people could be affected by your decisions. You notice details others overlook and are inclined to ask whether something should be done, not merely whether it can be done. Reliability is one of your quiet strengths.","fingerprint":[0.8,0.35,0.55,0.3,0.55,0.95,0.6,0.65],"classification":"COMPUTER TECHNICIAN","accent":"#D8C49A","image":"assets/characters/MA.png"},"RI":{"name":"RITSUKO AKAGI","title":"The Analytical Synchronisation","quote":"Science is the power of human beings.","traits":"Analysis · Competence · Logic · Control","blurb":"You prefer understanding to guessing and evidence to assumption. Competence gives you security, and you approach difficult situations by breaking them into manageable systems. Rationality can sometimes become a shield against emotions that are much less controllable.","fingerprint":[0.25,0.55,0.95,0.7,0.65,0.75,0.3,0.45],"classification":"CHIEF SCIENTIST","accent":"#FF8A33","image":"assets/characters/RI.png"},"AO":{"name":"SHIGERU AOBA","title":"The Signal Synchronisation","quote":"No abnormalities detected.","traits":"Observation · Independence · Scepticism · Technical thinking","blurb":"You are comfortable operating slightly outside the spotlight. You notice patterns, inconsistencies and changes without needing to make a spectacle of noticing them. You value independence and prefer clear communication without unnecessary drama.","fingerprint":[0.25,0.75,0.65,0.25,0.6,0.55,0.3,0.65],"classification":"COMPUTER TECHNICIAN","accent":"#8BA58D","image":"assets/characters/AO.png"},"KW":{"name":"KAWORU NAGISA","title":"The Connection Synchronisation","quote":"I was born to meet you.","traits":"Compassion · Acceptance · Authenticity · Connection","blurb":"You tend to look past people's defences and see the person underneath them. You do not necessarily require others to justify themselves before accepting them. Connection, authenticity and understanding matter more to you than conventional expectations.","fingerprint":[0.9,0.45,0.2,0.2,0.9,0.75,0.98,0.8],"classification":"FIFTH CHILD","accent":"#C9D6FF","image":"assets/characters/KW.png"},"HY":{"name":"MAKOTO HYUGA","title":"The Support Synchronisation","quote":"I'm counting on you.","traits":"Loyalty · Communication · Reliability · Supportiveness","blurb":"You are often at your best when helping someone else succeed. You pay attention to what people need, communicate when information matters and remain dependable under stress. You do not need to be in charge to be essential to a team.","fingerprint":[0.65,0.25,0.45,0.2,0.45,0.9,0.65,0.75],"classification":"COMPUTER TECHNICIAN","accent":"#B2A37B","image":"assets/characters/HY.png"},"PP":{"name":"PEN-PEN","title":"The Independent Synchronisation","quote":"…","traits":"Independence · Observation · Comfort · Curiosity","blurb":"You may be more perceptive than people realise. You appreciate comfort, familiar surroundings and control over your own space, while remaining curious about what happens around you. You do not feel compelled to participate in every drama—and that can make you surprisingly clear-sighted.","fingerprint":[0.35,0.9,0.25,0.1,0.7,0.3,0.2,0.7],"classification":"NERV MASCOT","accent":"#E5D6A4","image":"assets/characters/PP.png"},"MR":{"name":"MARI ILLUSTRIOUS MAKINAMI","title":"The Unpredictable Synchronisation","quote":"It's so exciting!","traits":"Curiosity · Spontaneity · Adaptability · Playfulness","blurb":"You are energised by novelty and tend to treat uncertainty as an invitation rather than a warning. You can be playful without being careless and serious without becoming solemn. Rules are useful when they serve a purpose, but you are happy to find another route when they do not.","fingerprint":[0.45,0.9,0.35,0.8,0.98,0.55,0.85,1.0],"classification":"FOURTH CHILD · REBUILD","accent":"#FF4FAD","image":"assets/characters/MR.png"},"TJ":{"name":"TOJI SUZUHARA","title":"The Grounded Synchronisation","quote":"I have my reasons for doing this.","traits":"Loyalty · Directness · Protectiveness · Groundedness","blurb":"You tend to meet difficult situations in a direct, practical way. Loyalty is personal rather than abstract: the people close to you matter, and protecting them can outweigh prestige or recognition. You may react bluntly at first, but you are capable of revising a judgement once you understand the person behind it.","fingerprint":[0.55,0.7,0.35,0.25,0.35,0.9,0.55,0.65],"classification":"FOURTH CHILD","accent":"#4F78B8","image":"assets/characters/TJ.png"}};
